import{_ as o,c as d,o as a,ag as s}from"./chunks/framework.KcKrU9KS.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"linux/Ubantu/ubantu安装与命令.md","filePath":"linux/Ubantu/ubantu安装与命令.md","lastUpdated":1773141133000}'),e={name:"linux/Ubantu/ubantu安装与命令.md"};function r(n,t,i,u,l,c){return a(),d("div",null,t[0]||(t[0]=[s('<h3 id="一、切换到-root-用户" tabindex="-1">一、切换到 root 用户 <a class="header-anchor" href="#一、切换到-root-用户" aria-label="Permalink to &quot;一、切换到 root 用户&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo su - root</span></span>\n<span class="line"><span>sudo su -</span></span></code></pre></div><h4 id="_2-使用-sudo-命令临时获得管理员权限-推荐" tabindex="-1">2. 使用 <code>sudo</code> 命令临时获得管理员权限<code>(推荐)</code> <a class="header-anchor" href="#_2-使用-sudo-命令临时获得管理员权限-推荐" aria-label="Permalink to &quot;2. 使用 `sudo` 命令临时获得管理员权限`(推荐)`&quot;">​</a></h4><p><code>sudo</code>（SuperUser Do）命令允许普通用户临时以管理员身份执行命令。</p><p><strong>切换到 root 用户：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo -i</span></span></code></pre></div><ul><li><strong><code>sudo -i</code></strong>：启动一个 root shell。</li></ul><h4 id="_3-使用-sudo-su-切换到-root-用户" tabindex="-1">3. 使用 <code>sudo su</code> 切换到 root 用户 <a class="header-anchor" href="#_3-使用-sudo-su-切换到-root-用户" aria-label="Permalink to &quot;3. 使用 `sudo su` 切换到 root 用户&quot;">​</a></h4><p>通过 <code>sudo</code> 切换到 root 用户。</p><h4 id="_4-使用-passwd-设置-root-密码" tabindex="-1">4. 使用 <code>passwd</code> 设置 root 密码 <a class="header-anchor" href="#_4-使用-passwd-设置-root-密码" aria-label="Permalink to &quot;4. 使用 `passwd` 设置 root 密码&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo passwd root</span></span></code></pre></div><h3 id="二、恢复为普通用户" tabindex="-1">二、恢复为普通用户 <a class="header-anchor" href="#二、恢复为普通用户" aria-label="Permalink to &quot;二、恢复为普通用户&quot;">​</a></h3><h4 id="_1-退出当前的-root-用户会话" tabindex="-1">1. 退出当前的 root 用户会话 <a class="header-anchor" href="#_1-退出当前的-root-用户会话" aria-label="Permalink to &quot;1. 退出当前的 root 用户会话&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>exit</span></span></code></pre></div><h4 id="_2-切换回普通用户-推荐" tabindex="-1">2.切换回普通用户<code>(推荐)</code> <a class="header-anchor" href="#_2-切换回普通用户-推荐" aria-label="Permalink to &quot;2.切换回普通用户`(推荐)`&quot;">​</a></h4><p>如果您是在 <code>root</code> 用户下，可以使用 <code>su</code> 或 <code>sudo</code> 切换回普通用户：</p><table tabindex="0"><thead><tr><th>方法</th><th>命令</th><th>密码要求</th><th>说明</th></tr></thead><tbody><tr><td>切换到 root 用户</td><td>sudo su - root</td><td>root用户的密码</td><td>直接切换到 root 用户并加载 root 用户环境。</td></tr><tr><td>临时获得管理员权限</td><td>sudo</td><td>当前用户的密码</td><td>使用当前用户的 sudo 权限来执行管理员命令。</td></tr><tr><td>通过 sudo 切换到 root</td><td>sudo su -</td><td>当前用户的密码</td><td>使用 sudo 切换到 root 用户，并加载 root 用户环境。</td></tr><tr><td>启动 root shell</td><td>sudo -i</td><td>当前用户的密码</td><td>启动一个新的 shell，模拟 root 用户环境。</td></tr><tr><td>设置 root 密码</td><td>sudo passwd root</td><td>当前用户的密码</td><td>在没有 root 密码的情况下，设置 root 用户密码。</td></tr><tr><td>切换回普通用户</td><td>exit</td><td>无</td><td>退出 root 用户会话，恢复为普通用户。</td></tr><tr><td>切换到指定普通用户</td><td>su - username</td><td>root 用户的密码</td><td>从 root 用户切换到指定的普通用户。</td></tr><tr><td>切换到普通用户 (sudo)</td><td>sudo -u username -i</td><td>当前用户的密码</td><td>使用 sudo 切换到指定的普通用户。</td></tr></tbody></table>',17)]))}const b=o(e,[["render",r]]);export{h as __pageData,b as default};
